My disjunctive facets become conjunctive when I set searchParameters.facetsExcludes

Example
---

Click the sony checkbox here:    https://codesandbox.io/s/l598wkxoy7


my code
---

I added this:

```
  excludeVendors = ["Entity Brands","JS Supplies"];
  var searchParameters = {};
  if(excludeVendors && excludeVendors.length>0) {
    searchParameters =  {
        facets: ['vendor'],
        "facetsExcludes": {
            "vendor": excludeVendors
        }
      };
  }

```

to this standard shopify code:

```
  var _ = algolia._,
      $ = algolia.jQuery;

  algolia.config.results_selector += ', .algolia-shopify-instantsearch';

  var $hiding = $('<style>' + algolia.config.results_selector + ' { visibility: hidden }</style>');
  $hiding.appendTo($('head'));

  algolia.facetsWidgets.forEach(function(element) { if(!element.params.sortBy) element.params.showMore = true; });
  
  var instant = algolia.instantsearch = {
    colors: algolia.config.colors,
    distinct: !!algolia.config.show_products,
    facets: {
